        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def runs_bar(g):
    # maximal runs of 5 length>=2, horizontal and vertical
    bars=[]
    h,w=len(g),len(g[0])
    for i in range(h):
        j=0
        while j<w:
            if g[i][j]==5:
                k=j
                while k<w and g[i][k]==5: k+=1
                if k-j>=2: bars.append(('h',i,j,k-1))
                j=k
            else: j+=1
    for j in range(w):
        i=0
        while i<h:
            if g[i][j]==5:
                k=i
                while k<h and g[i][k]==5: k+=1
                if k-i>=2: bars.append(('v',j,i,k-1))
                i=k
            else: i+=1
    return bars

def component(g,seed,seen):
    h,w=len(g),len(g[0])
    stack=[seed]; comp=[]
    while stack:
        r,c=stack.pop()
        if (r,c) in seen: continue
        seen.add((r,c))
        if not(0<=r<h and 0<=c<w) or g[r][c] in (0,5): continue
        comp.append((r,c))
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            stack.append((r+dr,c+dc))
    return comp

def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    bars=runs_bar(g)
    seen=set()
    for kind,a,b,e in bars:  # h: row a, cols b..e ; v: col a, rows b..e
        cells=set()
        if kind=='h':
            barcells={(a,j) for j in range(b,e+1)}
            seeds=[(a+dr,j) for j in range(b,e+1) for dr in (-1,1) if 0<=a+dr<h and g[a+dr][j] not in (0,5)]
        else:
            barcells={(i,a) for i in range(b,e+1)}
            seeds=[(i,a+dc) for i in range(b,e+1) for dc in (-1,1) if 0<=a+dc<w and g[i][a+dc] not in (0,5)]
        comp=[]
        for s in seeds: comp+=component(g,s,seen)
        if not comp: continue
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        rows=set(range(b,e+1)) if kind=='v' else {a}|set(range(r0,r1+1))
        cols=set(range(b,e+1)) if kind=='h' else {a}|set(range(c0,c1+1))
        R0,R1,C0,C1=min(rows),max(rows),min(cols),max(cols)
        H=r1-r0+1; W=c1-c0+1
        blk=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        for r in range(R0,R1+1):
            for c in range(C0,C1+1):
                if out[r][c]==0:
                    out[r][c]=blk[(r-r0)%H][(c-c0)%W]
    return out

